param(
  [string]$Port = "COM8",
  [int]$Baud = 921600,
  [string]$BindAddress = "127.0.0.1",
  [int]$TcpPort = 18443,
  [int]$Duration = 120
)
# Local bench bridge for WSL only. No MAVLink is generated by this bridge.
# Close the ground station first. Use native USB passthrough on the aircraft.
$ErrorActionPreference = "Stop"
Add-Type -TypeDefinition 'using System.Runtime.InteropServices; public static class UavTimer { [DllImport("winmm.dll")] public static extern uint timeBeginPeriod(uint p); [DllImport("winmm.dll")] public static extern uint timeEndPeriod(uint p); }'
[void][UavTimer]::timeBeginPeriod(1)
$serial = New-Object System.IO.Ports.SerialPort $Port,$Baud,"None",8,"One"
$listener = New-Object System.Net.Sockets.TcpListener ([System.Net.IPAddress]::Parse($BindAddress)),$TcpPort
$client = $null
try {
  $serial.Open()
  $serial.ReadTimeout = 20
  $serial.WriteTimeout = 20
  $listener.Start(1)
  Write-Output "Bridge $Port @ $Baud -> ${BindAddress}:$TcpPort, waiting for one WSL client"
  $end = [DateTime]::UtcNow.AddSeconds($Duration)
  while (-not $listener.Pending()) {
    if ([DateTime]::UtcNow -ge $end) { throw "Client connection timeout" }
    Start-Sleep -Milliseconds 10
  }
  $client = $listener.AcceptTcpClient()
  $client.NoDelay = $true
  $stream = $client.GetStream()
  $stream.WriteTimeout = 100
  $buffer = New-Object byte[] 16384
  $rxCount = 0
  $txCount = 0
  while ([DateTime]::UtcNow -lt $end) {
    if ($client.Client.Poll(0,[System.Net.Sockets.SelectMode]::SelectRead) -and $client.Available -eq 0) { break }
    if ($stream.DataAvailable) {
      $n = $stream.Read($buffer,0,$buffer.Length)
      if ($n -eq 0) { break }
      $serial.Write($buffer,0,$n)
      $txCount += $n
    }
    if ($serial.BytesToRead -gt 0) {
      $n = $serial.Read($buffer,0,[Math]::Min($serial.BytesToRead,$buffer.Length))
      $stream.Write($buffer,0,$n)
      $rxCount += $n
    }
    Start-Sleep -Milliseconds 1
  }
  Write-Output "Bridge closed, FCU->WSL=$rxCount bytes, WSL->FCU=$txCount bytes"
} finally {
  if ($client) { $client.Close() }
  $listener.Stop()
  if ($serial.IsOpen) { $serial.Close() }
  [void][UavTimer]::timeEndPeriod(1)
}
